def bisect(f, a, b, tol=1e-10, nmax=200):
    fa = f(a)
    for _ in range(nmax):
        m = 0.5*(a+b)
        fm = f(m)
        if abs(fm) == 0 or 0.5*(b-a) < tol:
            return m
        if (fa < 0) != (fm < 0):
            b = m
        else:
            a, fa = m, fm
    return 0.5*(a+b)

def newton(f, df, x0, tol=1e-12, nmax=100):
    x = x0
    for _ in range(nmax):
        fx = f(x)
        if abs(fx) < tol:
            return x
        x = x - fx/df(x)
    return x

def secant(f, x0, x1, tol=1e-12, nmax=100):
    f0, f1 = f(x0), f(x1)
    for _ in range(nmax):
        if abs(f1) < tol:
            return x1
        x2 = x1 - f1*(x1 - x0)/(f1 - f0)
        x0, f0, x1, f1 = x1, f1, x2, f(x2)
    return x1

def fixed_point(g, x0, tol=1e-12, nmax=1000):
    x = x0
    for _ in range(nmax):
        xn = g(x)
        if abs(xn - x) < tol:
            return xn
        x = xn
    return x
