import math
def order(errs):
    return [math.log(errs[k+1]/errs[k])/math.log(errs[k]/errs[k-1])
            for k in range(1, len(errs)-1)]

def lagrange(xs, ys, x):
    n = len(xs); total = 0.0
    for i in range(n):
        term = ys[i]
        for j in range(n):
            if j != i:
                term *= (x - xs[j])/(xs[i] - xs[j])
        total += term
    return total

def divided_diff(xs, ys):
    n = len(xs); c = list(ys)
    for k in range(1, n):
        for i in range(n-1, k-1, -1):
            c[i] = (c[i]-c[i-1])/(xs[i]-xs[i-k])
    return c   # Newton coefficients

def newton_eval(xs, c, x):
    p = c[-1]
    for k in range(len(xs)-2, -1, -1):
        p = p*(x-xs[k]) + c[k]
    return p

