def adaptive_simpson(f, a, b, tol):
    def simp(a, b):
        c = 0.5*(a+b)
        return (b-a)/6*(f(a)+4*f(c)+f(b))
    def rec(a, b, whole, tol):
        c = 0.5*(a+b)
        left, right = simp(a, c), simp(c, b)
        if abs(left+right-whole) <= 15*tol:
            return left+right+(left+right-whole)/15
        return rec(a, c, left, tol/2)+rec(c, b, right, tol/2)
    return rec(a, b, simp(a, b), tol)

