import numpy as np
def gauss_seidel(A, b, x, iters):
    n = len(b)
    for _ in range(iters):
        for i in range(n):
            s = A[i,:] @ x - A[i,i]*x[i]
            x[i] = (b[i] - s) / A[i,i]
    return x

import numpy as np
def sor(A, b, x, omega, iters):
    n = len(b)
    for _ in range(iters):
        for i in range(n):
            s = A[i,:] @ x - A[i,i]*x[i]
            xgs = (b[i] - s)/A[i,i]
            x[i] = (1-omega)*x[i] + omega*xgs
    return x

import numpy as np
def power_iteration(A, iters=1000):
    x = np.random.rand(A.shape[0])
    for _ in range(iters):
        x = A @ x; x = x/np.linalg.norm(x)
    return (x @ A @ x)/(x @ x), x   # eigenvalue, eigenvector

import numpy as np
def qr_algorithm(A, iters=500):
    Ak = A.astype(float).copy()
    for _ in range(iters):
        Q, R = np.linalg.qr(Ak)
        Ak = R @ Q
    return np.diag(Ak)   # eigenvalues (real symmetric case)

import numpy as np
# spectral derivative of a periodic function via FFT
def spectral_derivative(u, L):
    n = len(u)
    k = 2*np.pi*np.fft.fftfreq(n, d=L/n)
    return np.real(np.fft.ifft(1j*k*np.fft.fft(u)))
